App.boot({id:'dashboard',title:'Dashboard',render(el){const {money,num,esc,icon,barChart,donut}=U,S=Store,db=S.db,fs=App.farm(),u=App.user();
 const a=db.farms.find(x=>x.name===fs)||{acres:0,seri:0};const haris=db.haris.filter(h=>h.farm===fs);const sales=db.sales.filter(x=>x.farm===fs);
 const inc=sales.reduce((s,x)=>s+x.amount,0),exp=S.allExpenses().filter(x=>x.farm===fs).reduce((s,x)=>s+x.amount,0),adv=db.advances.filter(x=>x.farm===fs).reduce((s,x)=>s+x.amount,0),pend=S.pending(fs).length;
 const kpi=(lbl,val,ic,sub='',cls='')=>`<div class="card kpi ${cls}"><div class="ic">${icon(ic)}</div><div><div class="lbl">${lbl}</div><div class="val">${val}</div><div class="sub">${sub}</div></div></div>`;
 const farmsV=App.visibleFarms();const perFarm=farmsV.map(f=>[db.sales.filter(x=>x.farm===f).reduce((s,x)=>s+x.amount,0),S.allExpenses().filter(x=>x.farm===f).reduce((s,x)=>s+x.amount,0)]);
 const shown=farmsV.map((f,i)=>({f,v:perFarm[i]})).filter(x=>x.v[0]||x.v[1]);
 const cats={};S.allExpenses().filter(x=>x.farm===fs).forEach(x=>cats[x.category]=(cats[x.category]||0)+x.amount);
 const role=u.role,roleNote=role==='supervisor'?'Stock receiving, usage and field overview':role==='accountant'?'Hari ledgers, income, expenses and stock usage':'Farm records and office review';
 el.innerHTML=`<section class="hero">${U.fieldArt()}<div class="hero-inner"><div><span class="chip">${icon('sprout')} ${esc(App.season())} • ${esc(fs)}</span><h2>${new Date().getHours()<12?'Subha bakhair':'Assalam o Alaikum'}, ${esc(u.name)} 👋</h2><p>${esc(S.ROLES[role])} • ${esc(roleNote)}. ${pend?pend+' entries are waiting for office approval.':'Everything is approved and up to date.'}</p></div><div class="row"><a class="btn secondary" href="settlements.html">${icon('book')} Hari ledgers</a>${App.isOffice()?`<a class="btn" href="approvals.html">${icon('checks')} Review ${pend} pending</a>`:`<a class="btn" href="usage.html">${icon('plus')} Record usage</a>`}</div></div></section>
 <div class="grid g4">${kpi('Total physical acres',num(a.acres),'farm',`Seri ${num(a.seri)} • Hari land ${num(a.acres-a.seri)}`)}${kpi('Hari accounts',haris.length,'hari',`${num(haris.reduce((s,h)=>s+S.hariAcres(h),0))} crop acres assigned`,'gold')}${kpi('Recorded sales',money(inc),'cash',`${sales.length} sale entries`,'blue')}${kpi('Recorded costs',money(exp),'receipt',`Advances ${money(adv)} (ledger deduction)`,'red')}</div>
 <div class="grid g3" style="margin-top:16px"><div class="card span2"><div class="card-head"><div><h3>Sales vs costs by farm</h3><p>${App.isOffice()?'All active farms with entries':'Your assigned farm'}</p></div></div>${shown.length?barChart([shown.map(x=>x.v[0]),shown.map(x=>x.v[1])],{labels:shown.map(x=>x.f),names:['Sales','Costs']}):U.empty('No sales or costs yet','Record sales and expenses to see the chart.','chart')}</div>
 <div class="card"><div class="card-head"><div><h3>Cost breakdown</h3><p>${esc(fs)}</p></div></div>${donut(Object.entries(cats).map(([label,value])=>({label,value})))}</div></div>
 <div class="grid g3" style="margin-top:16px"><div class="card span2"><div class="card-head"><div><h3>Hari balances</h3><p>Pending entries are included in this preview.</p></div><a class="btn ghost" href="settlements.html">Open ledgers →</a></div><div id="hb"></div></div>
 <div class="card"><div class="card-head"><h3>Farm stock (remaining)</h3><a class="btn ghost" href="usage.html">Details →</a></div><ul class="list">${S.ITEMS.map(it=>{const q=S.farmQty(fs,it);return `<li><span class="dot">${it[0]}</span><div style="flex:1"><b>${it}</b><div class="bar"><i style="width:${Math.min(100,q)}%"></i></div></div><b>${num(q)}</b></li>`}).join('')}</ul>
 ${pend?`<div class="alert" style="margin-top:12px">${icon('alert')}<span>${pend} entr${pend===1?'y':'ies'} on this farm waiting for office approval.</span></div>`:''}</div></div>
 ${App.isOffice()?`<div class="card" style="margin-top:16px"><div class="card-head"><h3>Accessible farms</h3><a class="btn ghost" href="farms.html">Manage →</a></div><div class="grid g4">${db.farms.filter(f=>!f.archived).map(f=>`<div class="farm-card"><b>${esc(f.name)}</b><div class="meta">${f.acres?num(f.acres)+' acres • Seri '+num(f.seri):'Acreage not set'}${f.location?' • '+esc(f.location):''}</div></div>`).join('')}</div></div>`:''}
 <p class="muted small" style="margin-top:14px">Physical acreage is not summed across Rabi and Kharif. Demo sample records are illustrative.</p>`;
 U.dataTable(document.getElementById('hb'),{search:false,emptyTitle:'No Hari on this farm',emptyText:'Add a Hari from “Hari & Crop Acres”.',rows:haris.map(h=>({h,l:S.ledger(h)})),columns:[{label:'Hari',value:r=>r.h.name},{label:'Acres',num:1,value:r=>S.hariAcres(r.h)},{label:'Hari share',num:1,value:r=>r.l.gross,html:r=>money(r.l.gross)},{label:'Deductions',num:1,value:r=>r.l.ded,html:r=>money(r.l.ded)},{label:'Advances',num:1,value:r=>r.l.advance,html:r=>money(r.l.advance)},{label:'Balance',num:1,value:r=>r.l.balance,html:r=>`<b class="${r.l.balance<0?'neg':'pos'}">${money(r.l.balance)}</b>`}]})}});
